FROM (VALUES ('A',@T1_R3_PairA),('B',@T1_R3_PairB),('C',@T1_R3_PairC),('D',@T1_R3_PairD),('E',@T1_R3_PairE),('F',@T1_R3_PairF)) AS r(RowLetter, PairGroupId)
